import {pageHeader,backButton,disclosure} from '../primitives.js?v=66';

const probabilityList = (title, rows) => `<section class="faq-probability-group"><h3>${title}</h3><dl class="probability-list">${rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}%</dd></div>`).join('')}</dl></section>`;
const chestProbabilities = () => `<div class="chest-probabilities">${probabilityList('Что выпадает',[['Одна фигура',85],['Одна доска',10],['15 осколков',5]])}${probabilityList('Редкость предмета',[['Обычный',60],['Редкий',30],['Эпический',9],['Легендарный',1]])}<section class="faq-guarantee"><h3>Гарантия</h3><p>Десятое открытие без эпического или легендарного предмета гарантирует одну из этих редкостей.</p>${probabilityList('Редкость на гарантии',[['Эпический',90],['Легендарный',10]])}${probabilityList('Тип предмета на гарантии',[['Фигура',90],['Доска',10]])}<p>Повторы возможны и компенсируются осколками.</p></section></div>`;

export const faqPage = () => `<section id="faq" class="tab" data-page-kind="subpage" hidden>${pageHeader({title:"Вопросы и ответы",startContent:backButton('profile')})}<div class="page-content">${disclosure("Как начисляются монеты?","<article class=\"panel\"><p>Монеты начисляются после завершённой партии. После игры вы увидите итог и разбор того, из чего сложилась награда. На монеты открывают сундуки и пополняют коллекцию.</p></article>")}${disclosure("Что выпадает из сундука?","<article class=\"panel\">"+chestProbabilities()+"</article>")}${disclosure("Для чего нужны осколки?","<article class=\"compensation panel\"><div><p>Монеты нужны для сундуков. Осколки — для создания конкретных фигур и досок. Обменять осколки обратно на монеты нельзя.</p><button class=\"quiet\" data-go=\"collection\">Открыть коллекцию</button></div><div class=\"table-scroll\"><table><caption>Осколки за повтор / стоимость создания</caption><thead><tr><th>Редкость</th><th>Фигура</th><th>Доска</th></tr></thead><tbody><tr><td>Обычная</td><td>8 / 40</td><td>16 / 80</td></tr><tr><td class=\"rare\">Редкая</td><td>20 / 100</td><td>40 / 200</td></tr><tr><td class=\"epic\">Эпическая</td><td>60 / 300</td><td>120 / 600</td></tr><tr><td class=\"legendary\">Легендарная</td><td>150 / 750</td><td>300 / 1500</td></tr></tbody></table></div></article>")}${disclosure("Что означают очки?","<article class=\"panel\"><p>Очки показывают разницу в материале на доске. Пешка — 1, конь и слон — 3, ладья — 5, ферзь — 9. Это не рейтинг и не валюта.</p></article>")}${disclosure("Как подбирается соперник?","<p>ИИ подстраивается под результаты ваших партий и может немного менять силу от игры к игре. Это внутренняя система GachaChess, а не официальный Elo.</p><p><a href=\"./engine-info.html\" target=\"_blank\" rel=\"noopener\">Как устроен ИИ</a></p>")}${disclosure("Когда можно сдаться?","<article class=\"panel\"><p>Сдача до первого вашего хода отменяет партию. После первого хода она считается поражением. Незавершённые партии и партии, отменённые из-за ошибки ИИ, награду не дают.</p></article>")}${disclosure("Как работает календарь активности?","<article class=\"panel\"><p>Первую завершённую партию за день календарь отмечает как закрытый день. Результат и следующие партии этого дня на отметку не влияют. Последовательные дни образуют серию, но отдельных наград за неё нет.</p></article>")}</div></section>`;
